class Learner:
    def __init__(self, name, xp):
        self.name = name
        self.xp = xp
learner = Learner('Ama', 120)
print(learner.name)

class Lesson:
    def __init__(self, title):
        self.title = title
    def label(self):
        return f'Lesson: {self.title}'
print(Lesson('Loops').label())

from dataclasses import dataclass
@dataclass
class Course:
    name: str
    lesson_count: int
print(Course('Python', 10))

class Progress:
    def __init__(self, done, total):
        self.done = done
        self.total = total
    def percent(self):
        return 0 if self.total == 0 else self.done / self.total * 100
print(Progress(4, 10).percent())
